using Microsoft.AspNetCore.Mvc; using MovieTicketBooking.Web.Models; using MovieTicketBooking.Web.Services;
namespace MovieTicketBooking.Web.Controllers;
public class AccountController:Controller { readonly MovieStore s; public AccountController(MovieStore s)=>this.s=s; [HttpGet] public IActionResult Register(string? returnUrl=null){ViewBag.ReturnUrl=returnUrl;return View();} [HttpPost] public IActionResult Register(RegisterVm m,string? returnUrl=null){if(string.IsNullOrWhiteSpace(m.Name)||string.IsNullOrWhiteSpace(m.Email)||string.IsNullOrWhiteSpace(m.Password)){ViewBag.Error="Please fill all fields.";return View(m);} if(s.Customers.Any(x=>x.Email.Equals(m.Email,StringComparison.OrdinalIgnoreCase))){ViewBag.Error="Email already registered.";return View(m);} var c=new Customer{CustomerID=new Random().Next(10000,99999),CustomerName=m.Name.Trim(),City=m.City.Trim(),Email=m.Email.Trim(),Password=m.Password}; s.Customers.Add(c); s.Save(); HttpContext.Session.SetInt32("CustomerId",c.CustomerID); return !string.IsNullOrWhiteSpace(returnUrl)&&Url.IsLocalUrl(returnUrl)?Redirect(returnUrl):RedirectToAction("Index","Home");} [HttpGet] public IActionResult Login(string? returnUrl=null){ViewBag.ReturnUrl=returnUrl;return View();} [HttpPost] public IActionResult Login(string email,string password,string? returnUrl=null){var c=s.Customers.FirstOrDefault(x=>x.Email.Equals(email,StringComparison.OrdinalIgnoreCase)&&x.Password==password); if(c==null){ViewBag.Error="Invalid email or password.";return View();} HttpContext.Session.SetInt32("CustomerId",c.CustomerID);return !string.IsNullOrWhiteSpace(returnUrl)&&Url.IsLocalUrl(returnUrl)?Redirect(returnUrl):RedirectToAction("Index","Home");} public IActionResult Logout(){HttpContext.Session.Clear();return RedirectToAction("Index","Home");} }
